import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"SpatialVLA: Exploring Spatial Representations for Visual-Language-Action Model","description":"","frontmatter":{"title":"SpatialVLA: Exploring Spatial Representations for Visual-Language-Action Model","arxiv":"2501.15830","date":"2025-01-27","authors":"Delin Qu, Haoming Song, Qizhi Chen, Yuanqi Yao, Xinyi Ye, Yan Ding, Zhigang Wang, JiaYuan Gu, Bin Zhao, Dong Wang, Xuelong Li","categories":"cs.RO, cs.AI","topics":"通用具身智能, VLA 模型, 空间表征","outline":[2,2]},"headers":[],"relativePath":"papers/2501.15830.md","filePath":"papers/2501.15830.md","lastUpdated":null}'),l={name:"papers/2501.15830.md"};function e(i,s,m,r,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="spatialvla-exploring-spatial-representations-for-visual-language-action-model" tabindex="-1">SpatialVLA: Exploring Spatial Representations for Visual-Language-Action Model <a class="header-anchor" href="#spatialvla-exploring-spatial-representations-for-visual-language-action-model" aria-label="Permalink to &quot;SpatialVLA: Exploring Spatial Representations for Visual-Language-Action Model&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2501.15830" target="_blank" rel="noreferrer">2501.15830</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-01-27</td></tr><tr><td><strong>作者</strong></td><td>Delin Qu, Haoming Song, Qizhi Chen, Yuanqi Yao, Xinyi Ye, Yan Ding, Zhigang Wang, JiaYuan Gu, Bin Zhao, Dong Wang, Xuelong Li</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>用单目估计深度做 Ego3D 位置编码把 3D 结构注入观测，再按动作分布拟合的高斯把连续动作切成自适应空间栅格，使一步动作只需 3 个 token 且能在新机器人上重新切分栅格迁移。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>本文依据 arXiv <strong>v5</strong>（2025-05-19，abs 页给出的 HTML 版本）撰写，期刊信息为 Robotics: Science and Systems 2025。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>VLA 模型把预训练 VLM 接上动作头，在跨机器人数据上微调，已经能做出可迁移的通用操作策略。但这条路线有一个被绕过去的缺口：模型看到的始终是 2D 图像 token，输出的是按每个维度线性均分 256 个 bin 的离散动作。前者意味着模型必须从像素里隐式猜出物体离夹爪多远，后者意味着不同机器人的「向前 1 厘米」被映射到完全不同的 token 上。</p><p>这两件事在跨本体训练时会同时爆炸。相机装在腕上还是第三人称、装多高、焦距多少，各家不一样，所以观测根本不在同一个 3D 参考系里；自由度、控制器、工作空间大小不一样，所以动作的统计分布差好几个数量级。本文要解决的就是：<strong>在不要求任何机器人-相机外参标定的前提下，给 VLA 的输入端和输出端各造一套与具体本体无关的空间对齐表示</strong>。做成了，跨本体预训练才可能真的共享空间知识，而不只是共享视觉语义。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>RT-2 与 OpenVLA 确立了「动作即 token」的范式：把每个动作维度归一化后线性切 256 份，当成语言词表里的特殊 token 自回归预测。这套做法工程上极简，但线性均分假设动作在值域上均匀分布，而真实机器人动作高度集中在零附近，于是绝大多数 bin 常年空置，模型把容量浪费在几乎不出现的大幅动作上。Octo 与 HPT 走另一条路，用本体特定的 stem 或 head 把异构数据投到共享空间，代价是每个新本体都要一个新模块，动作空间本身仍未对齐。RDT 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 换成扩散/流匹配连续动作头，回避了离散化问题，但也放弃了自回归 VLM 的 token 级复用。</p><p>感知侧，3D-LLM、LLaVA-3D、LEO、3D-VLA 已经把 LLM/VLM 扩到 3D 输入，能做 3D 问答、定位、规划。它们的注意力全在「理解 3D 世界」上，动作空间仍然是平的。作者的判断是：3D 感知与 3D 动作必须成对出现才有意义——只把观测抬到 3D 而动作还是按轴线性分桶，模型学到的空间结构在输出端会被重新打散。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>先看已知的失败模式。OpenVLA 在 SimplerEnv 的 Variant Aggregation（改光照、材质、相机位姿）上明显掉分，说明 2D token 对视觉外观扰动敏感；同时它在跨本体数据上预训练后零样本能力有限，需要针对新机器人重训动作头。</p><p>顺着「为什么对相机位姿敏感」往下想：如果模型知道每个像素在<strong>相机自身坐标系</strong>里的 3D 位置，那么相机挪动时物体的语义特征不变、位置编码随之改变，这是一个自洽的表示，而且完全不需要知道相机相对机器人基座的外参。深度可以用现成单目深度估计器补上——这一步不是为了拿到精确尺度，而是为了拿到一个稳定的相对布局。</p><p>再看输出端。既然动作分布高度集中，那就别按值域均分，按<strong>概率均分</strong>：拟合一个高斯，让每个 bin 承担相同的概率质量，密集区自动切得细。更进一步，平移动作转成极坐标 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">ϕ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="mclose">)</span></span></span></span> 后，方向与距离解耦，可以给方向多分格子。这样一步动作只需要「平移格 + 旋转格 + 夹爪」三个 token，而不是七个。最后一步是顺理成章的：既然栅格由高斯参数决定，换机器人时重新拟合一个高斯、把新格子的 embedding 用旧格子做三线性插值初始化，就是天然的后训练接口。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>让 VLA 在换相机、换机器人时掉分的，是观测和动作都没有共同的空间参照系。SpatialVLA 的做法是给两端各装一个与本体无关的锚：观测端用相机自身坐标系下的 3D 位置编码，动作端用按动作概率密度切分的空间栅格。两个锚都只依赖「这一批数据自己的统计量」，不依赖任何跨机器人标定，因此可以在新场景上被重新计算而不是被重新学习。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以「把绿色杯子放到白盘子上」为例，一次推理的完整流程：</p><ul><li><strong>输入</strong>：一张 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">224</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">224</span></span></span></span> 的第三人称 RGB 图 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5944em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与指令 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6861em;"></span><span class="mord mathbf">L</span></span></span></span>。</li><li><strong>Ego3D 位置编码</strong>：ZoeDepth 估计深度图，配合相机内参反投影得到每个像素的相机系 3D 坐标 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6861em;"></span><span class="mord mathbf">P</span></span></span></span>；SigLIP 编码出 2D 语义特征 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6861em;"></span><span class="mord mathbf">X</span></span></span></span>；两者相加 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8361em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">O</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathbf mtight">3d</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7694em;vertical-align:-0.0833em;"></span><span class="mord mathbf">X</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">MLP</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span><span class="mopen">(</span><span class="mord mathbf">P</span><span class="mclose">))</span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0556em;">γ</span></span></span></span> 是正弦编码。</li><li><strong>VLM 主干</strong>：PaliGemma2 接收 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8361em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">O</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathbf mtight">3d</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与文本 token，自回归输出动作 token。文本 embedding 全程冻结。</li><li><strong>动作栅格与去 token 化</strong>：平移转极坐标后与旋转各自查自适应栅格，得到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8361em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">trans</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8361em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathbf">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">rot</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4096</span></span></span></span>、加夹爪共 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">8194</span></span></span></span> 个动作 token；一步动作 3 个 token，chunk <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span> 即 12 个 token，解码回连续 7 维动作后做 action ensemble 下发。</li><li><strong>后训练</strong>：在新数据上重拟合高斯、重切栅格，新 token embedding 由旧栅格三线性插值初始化，再全参或 LoRA 微调。</li></ul><p>预训练规模：OXE 子集 + RH20T 共 110 万条真机 episode，64 张 A100 跑 10 天，batch 2048；第二阶段移除 DROID 再训 4 万步。部署时 8.5 GB 显存、单张 RTX 4090 约 20 Hz。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>栅格切分是全文唯一实质的形式化。设某个归一化到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">−</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span> 的动作变量在整个数据混合上拟合出高斯 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal" style="margin-right:0.1474em;">N</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">μ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">a</span></span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord">Σ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">a</span></span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，密度为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span></span></span></span>，则 M 个区间的边界由等概率条件确定：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathrm mtight">M</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.4263em;vertical-align:-1.012em;"></span><span class="mop">ar<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6679em;"><span style="top:-2.4em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3173em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span><span class="mpunct mtight">,</span><span class="minner mtight">…</span><span class="mpunct mtight">,</span><span class="mord mtight"><span class="mord mathnormal mtight">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.3567em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord mathrm mtight">M</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1433em;"><span></span></span></span></span></span></span></span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">min</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.8361em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop"><span class="mop op-symbol large-op" style="margin-right:0.4445em;position:relative;top:-0.0011em;">∫</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.4143em;"><span style="top:-1.7881em;margin-left:-0.4445em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3281em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span><span style="top:-3.8129em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3281em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2025em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.012em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mopen">(</span><span class="mord mathnormal">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">d</span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:2.0074em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.3214em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathrm">M</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:1em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">i</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathrm">M</span></span></span></span></span></p><p>直观说这就是取分布的<strong>分位数</strong>作为格点。线性均分让每个 bin 覆盖等长的值域，等概率均分让每个 bin 覆盖等量的样本；在动作高度集中于零附近时，后者会把绝大多数格子放在小幅动作上，正是精细操作最需要分辨率的地方。</p><p>后训练的 embedding 初始化则是一个加权平均：新栅格第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 格的中心 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0747em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">ϕ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8247em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">new</span></span></span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8247em;"><span style="top:-2.453em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">new</span></span></span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8247em;"><span style="top:-2.453em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">new</span></span></span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 在旧栅格中找到 K 个相邻格，</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.2218em;vertical-align:-0.3471em;"></span><span class="mord"><span class="mord mathbf">e</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8747em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathfrak mtight">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1645em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">new</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3471em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.2421em;vertical-align:-1.4138em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.4138em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0269em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mord"><span class="mord mathbf">e</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8747em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span></span></span></span></span><span class="mpunct">,</span></span></span></span></span></p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0269em;">w</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0269em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 由中心距离归一化得到，即三线性插值。它成立的前提是「空间上相邻的动作栅格，其学到的 embedding 也应当相近」——这个前提在预训练规模足够大时是合理的，但论文没有直接度量 embedding 空间的这种局部平滑性，只给了图 7 的截面可视化。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>零样本能否直接控制？</strong> 在 SimplerEnv 上，Google Robot 的 Visual Matching 71.9%、Variant Aggregation 68.8%，微调后 75.1% / 70.7%；作为对照，RoboVLM 零样本 56.3%，闭源 RT-2-X 60.7% / 64.3%（55B 参数，本文 3.5B），open-pi-zero 复现的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 为 70.1% VM。WidowX 上零样本 34.4%、微调 42.7%。这里有一处值得直说：WidowX 微调后的总分提升几乎全部来自「把茄子放进篮子」从 79.2/70.8 涨到 100/100，而<strong>勺子任务的抓取与成功率反而从 25.0/20.8 掉到 20.8/16.7、胡萝卜抓取从 41.7 掉到 29.2</strong>，论文未讨论。</p><p><strong>能否作为新机器人的初始化？</strong> LIBERO 四个套件平均 78.1%，排名第一；但逐项看并非全胜——Object 上 89.9% 低于从零训练的 Diffusion Policy 的 92.5%，Goal 上 78.6% 低于 Octo 的 84.6%，相对 OpenVLA 的 76.5% 平均只高 1.6 个点。Franka 新本体上，单任务 82% 与 Diffusion Policy 的 81% 持平，优势集中在指令跟随（相对 OpenVLA +12%）与多任务（57%）。</p><p><strong>两个表示各贡献多少？</strong> 预训练消融在 Fractal + BridgeV2 混合集上做。线性 256 bin 换成自适应栅格，Google 两任务均值上 VA +36.5、VM +42.1，是全文最大的单项增益；去掉 Ego3D 编码后 VA 从 81.6/79.2 掉到 68.9/66.7。但同一张表里，去掉 Ego3D 后「抓胡萝卜」反而从 41.7% 升到 54.2%（成功率从 33.3% 掉到 12.5%），说明该编码改变的是完整放置而非抓取本身。栅格分辨率也非单调：6166 档的 Pick Coke Can VM 74.0% 与抓茄子 95.8% 都优于最终采用的 8194 档（70.7% / 91.7%）。</p><p><strong>后训练接口有多大用？</strong> 大规模数据上重切栅格只带来边际收益（Move Near VM +2.9%），小数据的 LIBERO 上则带来 +4.6/+5.1/+2.2/+5.4 个点。另外 LoRA 在小数据上全面优于全参微调（唯 Goal 除外）。附录还给了一个关键对照：不用深度 45.4%、用传感器深度 70.5%、用 ZoeDepth 估计深度 72.7%——<strong>估计深度比真实深度还好</strong>。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版</strong>：SpatialVLA 主张 VLA 的瓶颈是空间表示而非视觉语义；观测端用单目深度 + 相机系 3D 位置编码，绕开了机器人-相机外参标定；动作端按动作分布的分位数切自适应栅格，把一步动作压到 3 个 token；110 万 episode 预训练后在 SimplerEnv 双平台零样本领先，3.5B 参数超过 55B 的 RT-2-X；栅格可在新数据上重拟合并用三线性插值初始化，构成一个比全参微调更结构化的后训练接口。</p><p><strong>三句话版</strong>：把「3D 感知」和「3D 动作」成对做，才不会在输出端把空间结构打散。等概率栅格取代线性 256 bin 是全文最大的单项增益，Ego3D 编码主要提升对光照/材质/相机位姿变化的鲁棒性。所谓 3D 信息来自单目估计深度，本质是相对布局先验而非度量几何。</p><p><strong>一句话版</strong>：给 VLA 的输入和输出各装一个只依赖数据自身统计量、不依赖标定的空间锚点。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最要命的一条是：<strong>Ego3D 位置编码所注入的「3D 信息」是可靠的度量几何</strong>。这条假设一旦不成立，「空间理解」的整个叙事就要改写为「一个额外的低频布局先验」。</p><p>论文自己的证据恰恰指向后者。深度全部由冻结的 ZoeDepth 从单张 RGB 估计而来（作者说明是因为 OXE 与 RH20T 的 28 个数据集都没有深度），而附录的对照显示：换成真实传感器深度，准确率从 72.7% 降到 70.5%，作者的解释是传感器深度噪声大、ZoeDepth 更平滑，「捕捉相对空间布局即可，精确尺度并不必要」。这句话是诚实的，但它把 claim 从「3D 空间智能」降级为「一个平滑的相对深度通道」。此外单目度量深度在训练分布外的场景（反光桌面、透明物体、贴近相机的夹爪）会系统性失准，而这些恰恰是操作任务最关键的区域；论文没有在这类场景上报告任何深度误差或成功率分解。同一张消融表里「去掉 Ego3D 后抓取反而更好」也与该编码提供精确几何的解释不太相容。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做、不需要复现 110 万 episode 预训练的验证：</p><ul><li>取公开的 SpatialVLA checkpoint，在 LIBERO-Spatial 上做<strong>深度扰动</strong>推理：分别注入 (a) 恒定深度图（等价于关闭 3D 信息但保留 MLP 通路）、(b) 全局尺度缩放 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">0.5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">/2</span><span class="mord">×</span></span></span></span>、(c) 加性高斯噪声若干档。度量成功率随扰动强度的曲线。</li><li>若成功率对全局尺度几乎不敏感、对恒定深度明显下降，则「相对布局先验」的解读成立，「度量几何」的解读被削弱；若尺度缩放显著掉分，则支持论文的原始解释。</li><li>同批次做动作侧对照：把 8194 栅格换成同容量的线性栅格但<strong>不改其他任何东西</strong>（仅重映射 token 到值域均分区间），在 LIBERO 上重新 LoRA 微调，看等概率切分的增益在小数据后训练阶段是否仍然存在，还是只在预训练阶段成立。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>针对「跨本体空间知识可迁移」这一核心 claim，最有力的攻击是<strong>构造一个动作分布明显非高斯的本体</strong>。论文在 §V 自己承认高斯拟合在单轴运动等极端场景会把格子挤到某个坐标轴上、丢失其他轴的运动能力。据此可以设计：一台以离散关节步进为主的机械臂（动作分布是多峰甚至双模），或一个装配任务中平移分布呈强双峰（快速接近 + 微调插入）的数据集。预测的失败模式是：拟合出的单峰高斯把大量格子放在两个峰之间的低密度区，两个峰各自的分辨率反而低于线性均分。若成立，这说明增益来源不是「按分布自适应」，而只是「在这些数据集上动作恰好近似单峰集中」。</p><p>另一个替代解释针对 SimplerEnv 上的领先：SpatialVLA 的预训练混合中加入了 RH20T，并按真机测试表现调整了 OXE 的混合权重，而 OpenVLA/RoboVLM 用的是原始 OXE 权重。要排除「数据配方而非表示设计」的解释，需要一条用<strong>相同混合权重</strong>训练的线性 256-bin 基线，论文只在小规模消融里做了这个对照，主表没有。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>从「拟合动作分布」转向「学习动作度量」。</strong> 驱动它的局限是 §9 与 §11 指出的同一件事：高斯是对动作分布的<strong>外部</strong>参数化，与任务无关、与代价无关，因此它只能反映「哪些动作出现得多」，反映不了「哪些动作差异重要」。在插入、拧螺丝这类任务里，1 毫米的平移差别比 1 厘米更该被分开表示，但它出现的频率并不更高。</p><p>可借鉴的相邻工具是矢量量化与度量学习：不再拟合密度再取分位数，而是直接在动作空间上学一个由<strong>结果差异</strong>诱导的度量——两个动作若在同一状态下导致显著不同的后继观测，就应当落在不同的格子里。实现上可以把动作 tokenizer 换成以逆动力学一致性为目标训练的残差 VQ：codebook 的划分由「解码后重放能否复现观测转移」决定，而不是由边缘密度决定。这同时保留了本文的核心优点（离散 token、可自回归、可在新本体上重训 codebook），却把划分准则从与任务无关的统计量换成了与控制目标直接相关的量。</p><p>第一个实验很轻：在 Fractal + BridgeV2 上分别用 (a) 本文高斯分位数栅格、(b) 同容量的结果诱导 VQ 栅格训练同一个 3.5B 主干，在 SimplerEnv 的四个任务上比零样本成功率，并额外报告「同一格内动作导致的观测差异」的方差——如果新划分的类内方差显著更低而成功率不降，就说明动作离散化确实应该由动力学而非频率决定。</p>',49)])])}const d=a(l,[["render",e]]);export{o as __pageData,d as default};
